package com.cekalix.controlador;
import com.cekalix.dao.*;import com.cekalix.modelo.*;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/cotizaciones")
public class CotizacionServlet extends HttpServlet {private final CotizacionDAO dao=new CotizacionDAO();private final ClienteDAO cd=new ClienteDAO();private final ProductoDAO pd=new ProductoDAO();
protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("cotizaciones",dao.listar());q.setAttribute("clientes",cd.listar());q.setAttribute("productos",pd.listar());q.getRequestDispatcher("/WEB-INF/vistas/cotizaciones.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}
protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{Usuario u=(Usuario)q.getSession().getAttribute("usuarioSesion");String[] a=q.getParameterValues("productoId"),b=q.getParameterValues("cantidad");if(a==null||b==null||a.length!=b.length)throw new IllegalArgumentException("Agrega productos.");int[] ids=new int[a.length],cant=new int[b.length];for(int i=0;i<a.length;i++){ids[i]=Integer.parseInt(a[i]);cant[i]=Integer.parseInt(b[i]);}int id=dao.guardar(Integer.parseInt(q.getParameter("clienteId")),u.getIdUsuario(),ids,cant);q.getSession().setAttribute("mensaje","Cotización #"+id+" guardada.");p.sendRedirect(q.getContextPath()+"/cotizaciones");}catch(Exception e){q.getSession().setAttribute("error",e.getMessage());p.sendRedirect(q.getContextPath()+"/cotizaciones");}}
}